/* muscleShapesV2.js — avatar v2. Personaje original, sin IP.
 * viewBox "0 0 120 230", ningún path lleva transform.
 *
 * Figura: proporción humana heroica (≈8 cabezas), hombro ≈2.8 anchos de cabeza,
 * cintura estrecha, brazos separados del torso para que el hueco axilar exista y
 * el dorsal tenga contra qué leerse. Nada de proporción de juguete: el crecimiento
 * de un grupo nunca rebasa la silueta.
 *
 *   MUSCLES[view][id].levels[n]   n = nivel-1 (0..4 = Dormant..Peak)
 *      .fill[]   contorno del grupo -> TIER_COLORS[n]
 *      .shade[]  media luna inferior/externa, fill-rule="evenodd" (cel shading duro)
 *      .hi[]     media luna superior/interna, fill-rule="evenodd"
 *      .line[]   separación entre cabezas musculares (stroke). Aparece por nivel:
 *                el deltoide se parte en tres cabezas solo cuando hay densidad.
 *   MUSCLES[view][id].hit         área táctil constante entre niveles
 *   SILHOUETTE[view] / RIM[view]  cuerpo + luz de contorno (plata, 8-12%)
 *   INK[view]                     clavícula, esternón, columna, rodillas
 *
 * ORDEN DE PINTADO: SILHOUETTE -> INK -> (aura) -> por grupo fill, shade, hi, line -> hit -> RIM.
 */

export const VIEWBOX = '0 0 120 230';

/* Rampa de CALOR, un solo recorrido de matiz sin saltos: ceniza -> bronce ->
 * naranja -> naranja al rojo -> rojo incandescente. Cada tier es el mismo metal
 * más caliente que el anterior; nunca cambia de familia de color. La plata queda
 * para el cromo de la interfaz, no para los tiers. */
